    """Encuentra el siguiente número en el conjunto C2,3 que es mayor o igual a m."""
    n = m
    while True:
        temp = n
        while temp > 1:
            if temp % 2 == 0:
                temp //= 2
            elif temp % 3 == 0:
                temp //= 3
            else:
                break
        if temp == 1:
            return n
        n += 1

