def reverse_rows(matriz):
    return [row[::-1] for row in matriz]

def reverse_columns(matriz):
    return matriz[::-1]

def determine_transformation(matriz_a, matriz_b):
    if matriz_a == matriz_b:
        return "sin transformaciones"
    elif reverse_rows(matriz_a) == matriz_b:
        return "flip horizontal"
    elif reverse_columns(matriz_a) == matriz_b:
        return "flip vertical"
    elif reverse_columns(reverse_rows(matriz_a)) == matriz_b:
        return "flip vertical y flip horizontal"
    else:
        return "respuesta desconocida"

