def generate_primes(limit):
    """ Generate a list of prime numbers up to limit using the Sieve of Eratosthenes """
    is_prime = [True] * (limit + 1)
    p = 2
    while p * p <= limit:
        if is_prime[p]:
            for i in range(p * p, limit + 1, p):
                is_prime[i] = False
        p += 1
    return [p for p in range(2, limit + 1) if is_prime[p]]

def extract_prime_factors(number, primes):
    """ Extract unique prime factors of a number """
    factors = set()
    for prime in primes:
        if prime * prime > number:
            break
        while number % prime == 0:
            factors.add(prime)
            number //= prime
    if number > 1:
        factors.add(number)
    return factors

def calculate_prime_factors_sum(number, primes):
    """ Calculate the sum of unique prime factors of a number """
    factors = extract_prime_factors(number, primes)
    return sum(factors)

def precalculate_prime_factors_sums(upper_bound, primes):
    """ Precalculate the sum of unique prime factors for all numbers up to upper_bound """
    sums = [0] * (upper_bound + 1)
    for i in range(2, upper_bound + 1):
        sums[i] = calculate_prime_factors_sum(i, primes)
    return sums

def identify_ruth_aaron_pairs(start, end, sums):
    """ Identify Ruth-Aaron pairs between start and end """
    pairs = []
    for i in range(max(start, 2), end):
        if sums[i] == sums[i + 1]:
            pairs.append(f"{i} {i + 1}")
    return pairs

def primary_function():
    max_limit = 1000000
    primes = generate_primes(isqrt(max_limit) + 1)
    sums = precalculate_prime_factors_sums(max_limit, primes)

    data = input().strip().split()
    output = []

    for i in range(0, len(data), 2):
        a = int(data[i])
        b = int(data[i + 1])
        result = identify_ruth_aaron_pairs(a, b, sums)
        output.extend(result)

    sys.stdout.write("\n".join(output) + "\n")

