def explore(grid, i, j, seen):
    if i < 0 or i >= len(grid) or j < 0 or j >= len(grid[0]) or grid[i][j] == '#' or seen[i][j]:
        return 0
    seen[i][j] = True
    total = 1
    moves = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    for di, dj in moves:
        total += explore(grid, i + di, j + dj, seen)
    return total

def tally_reachable_spaces(grid):
    rows, cols = len(grid), len(grid[0])
    seen = [[False] * cols for _ in range(rows)]
    start_i = start_j = -1
    for row in range(rows):
        for col in range(cols):
            if grid[row][col] == '@':
                start_i, start_j = row, col
                break
        if start_i != -1:
            break
    return explore(grid, start_i, start_j, seen)

