import sys
import re

def process_input():
    return sys.stdin.read().splitlines()

def extract_words(lines):
    words = set()
    current_word = ""

    for line in lines:
        line = line.strip()
        if not line:
            continue

        parts = re.split(r'(?<!-)\s+', line)
        for part in parts:
            if part.endswith('-'):
                current_word += part[:-1]
            else:
                current_word += part
                word = re.sub(r'[^a-zA-Z-]', '', current_word).lower()
                if word:
                    words.add(word)
                current_word = ""

    return sorted(words)

def main():
    lines = process_input()
    words = extract_words(lines)
    for word in words:
        print(word)

if __name__ == "__main__":
    main()

