def explore(x, y, grid, explored):
    if x < 0 or x >= len(grid) or y < 0 or y >= len(grid[0]):
        return 0
    if grid[x][y] == '#' or explored[x][y]:
        return 0

    explored[x][y] = True
    count = 1

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    for dx, dy in directions:
        count += explore(x + dx, y + dy, grid, explored)

    return count

def solve_case(width, height, grid):
    visited = [[False] * height for _ in range(width)]

    start_x, start_y = -1, -1
    for i in range(width):
        for j in range(height):
            if grid[i][j] == '@':
                start_x, start_y = i, j
                break
        if start_x != -1:
            break

    if start_x != -1 and start_y != -1:
        return explore(start_x, start_y, grid, visited)

    return 0

