def factorize(n):
    divisors = []
    exp = 0
    # Divide by 2 as long as it's divisible
    while n % 2 == 0:
        exp += 1
        n //= 2
    if exp > 0:
        divisors.append(f"2^{exp}" if exp > 1 else "2")

    # Test with odd numbers
    divisor = 3
    while divisor * divisor <= n:
        exp = 0
        while n % divisor == 0:
            exp += 1
            n //= divisor
        if exp > 0:
            divisors.append(f"{divisor}^{exp}" if exp > 1 else str(divisor))
        divisor += 2

    # If a prime number greater than 2 remains
    if n > 1:
        divisors.append(str(n))

    return "*".join(divisors)

