def tally_primes(n, primes):
    tally = 0
    left = 0
    right = 0
    total = 0

    while left < len(primes) and primes[left] <= n:
        while right < len(primes) and total < n:
            total += primes[right]
            right += 1
        if total == n:
            tally += 1
        total -= primes[left]
        left += 1

    return tally

