MAX_LIMIT = 10**6
sieve = [True] * (MAX_LIMIT + 1)
primes = []

def initialize_sieve():
    sieve[0] = sieve[1] = False
    for i in range(2, int(math.sqrt(MAX_LIMIT)) + 1):
        if sieve[i]:
            for j in range(i * i, MAX_LIMIT + 1, i):
                sieve[j] = False

def is_prime_sieve(n):
    return sieve[n] if n <= MAX_LIMIT else is_prime_miller_rabin(n)

def is_prime_miller_rabin(n, k=5):
    if n <= 1 or (n % 2 == 0 and n > 2):
        return False
    d, r = n - 1, 0
    while d % 2 == 0:
        d //= 2
        r += 1

    def miller_test(a, d, n, r):
        x = pow(a, d, n)
        if x == 1 or x == n - 1:
            return True
        for _ in range(r - 1):
            x = pow(x, 2, n)
            if x == n - 1:
                return True
        return False

    return all(miller_test(random.randint(2, n - 2), d, n, r) for _ in range(k))

def fibonacci(n):
    if n in {0, 1}:
        return n
    def multiply_matrices(A, B):
        return [[A[0][0] * B[0][0] + A[0][1] * B[1][0], A[0][0] * B[0][1] + A[0][1] * B[1][1]],
                [A[1][0] * B[0][0] + A[1][1] * B[1][0], A[1][0] * B[0][1] + A[1][1] * B[1][1]]]
    def matrix_power(matrix, n):
        result = [[1, 0], [0, 1]]
        while n:
            if n % 2:
                result = multiply_matrices(result, matrix)
            matrix = multiply_matrices(matrix, matrix)
            n //= 2
        return result
    return matrix_power([[1, 1], [1, 0]], n - 1)[0][0]

