def sieve_of_eratosthenes(upper_bound):
    primes = [True] * (upper_bound + 1)
    primes[0] = primes[1] = False
    for number in range(2, int(upper_bound**0.5) + 1):
        if primes[number]:
            for multiple in range(number * number, upper_bound + 1, number):
                primes[multiple] = False
    return [num for num, is_prime in enumerate(primes) if is_prime]

def factorize(number, primes):
    factors = []
    for prime in primes:
        if prime * prime > number:
            break
        while number % prime == 0:
            factors.append(prime)
            number //= prime
    if number > 1:
        factors.append(number)
    return factors

def format_factors(number, factors):
    factor_counts = {}
    for factor in factors:
        if factor in factor_counts:
            factor_counts[factor] += 1
        else:
            factor_counts[factor] = 1

    formatted_factors = []
    for factor, count in sorted(factor_counts.items()):
        if count > 1:
            formatted_factors.append(f"{factor}^{count}")
        else:
            formatted_factors.append(str(factor))

    return f"{number} = {'*'.join(formatted_factors)}"

