from collections import deque
import heapq

def analyze_operations(ops):
    stack = []
    queue = deque()
    priority_queue = []

    possible_stack = True
    possible_queue = True
    possible_priority_queue = True

    for operation, value in ops:
        if operation == 1:
            stack.append(value)
            queue.append(value)
            heapq.heappush(priority_queue, -value)
        else:
            if possible_stack:
                if not stack or stack[-1] != value:
                    possible_stack = False
                else:
                    stack.pop()

            if possible_queue:
                if not queue or queue[0] != value:
                    possible_queue = False
                else:
                    queue.popleft()

            if possible_priority_queue:
                if not priority_queue or -priority_queue[0] != value:
                    possible_priority_queue = False
                else:
                    heapq.heappop(priority_queue)

    count_possible = sum([possible_stack, possible_queue, possible_priority_queue])

    if count_possible == 0:
        return "impossible"
    elif count_possible > 1:
        return "not sure"
    else:
        if possible_stack:
            return "stack"
        if possible_queue:
            return "queue"
        if possible_priority_queue:
            return "priority queue"

