def evaluate_predictions(games, predictions):
    outcomes = []

    for idx, pred in enumerate(predictions):

        if ">=" in pred:
            expr, val = pred.split(">=")
            op = ">="
        elif "<=" in pred:
            expr, val = pred.split("<=")
            op = "<="
        elif ">" in pred:
            expr, val = pred.split(">")
            op = ">"
        elif "<" in pred:
            expr, val = pred.split("<")
            op = "<"
        elif "=" in pred:
            expr, val = pred.split("=")
            op = "="
        else:
            raise ValueError("Operator not recognized in the prediction")

        game_names = expr.split("+")
        total = sum(games[game.strip()] for game in game_names)

        value_to_compare = float(val.strip())
        if op == ">=":
            is_correct = total >= value_to_compare
        elif op == "<=":
            is_correct = total <= value_to_compare
        elif op == ">":
            is_correct = total > value_to_compare
        elif op == "<":
            is_correct = total < value_to_compare
        elif op == "=":
            is_correct = abs(total - value_to_compare) < 1e-9  # Precise float comparison
        else:
            is_correct = False

        if is_correct:
            outcomes.append(f"Guess #{idx + 1} was correct.")
        else:
            outcomes.append(f"Guess #{idx + 1} was incorrect.")

    return outcomes


