def identify_structure(operations):
    stack = []
    queue = []
    priority_queue = []

    valid_stack = True
    valid_queue = True
    valid_priority_queue = True

    for operation in operations:
        operation_type, value = operation

        if operation_type == 1:
            stack.append(value)
            queue.append(value)
            heapq.heappush(priority_queue, -value)

        elif operation_type == 2:
            if valid_stack:
                if not stack or stack.pop() != value:
                    valid_stack = False
            if valid_queue:
                if not queue or queue.pop(0) != value:
                    valid_queue = False
            if valid_priority_queue:
                if not priority_queue or -heapq.heappop(priority_queue) != value:
                    valid_priority_queue = False

    possibilities = sum([valid_stack, valid_queue, valid_priority_queue])
    if possibilities > 1:
        return "not sure"
    elif possibilities == 1:
        if valid_stack:
            return "stack"
        elif valid_queue:
            return "queue"
        elif valid_priority_queue:
