def factorize(n):
    results = []
    exp = 0
    while n % 2 == 0:
        exp += 1
        n //= 2
    if exp > 0:
        results.append(f"2^{exp}" if exp > 1 else "2")

    divisor = 3
    while divisor * divisor <= n:
        exp = 0
        while n % divisor == 0:
            exp += 1
            n //= divisor
        if exp > 0:
            results.append(f"{divisor}^{exp}" if exp > 1 else str(divisor))
        divisor += 2

    if n > 1:
        results.append(str(n))

    return "*".join(results)

