def analyze_predictions():
    # Read the first value: number of matches and predictions
    first_line = input().strip()
    match_count, prediction_count = map(int, first_line.split())

    # Read match results and store them in a dictionary
    outcomes = {}
    for _ in range(match_count):
        match, percentage = input().strip().split()
        outcomes[match] = float(percentage)

    # Evaluate predictions
    for guess_number in range(1, prediction_count + 1):
        prediction = input().strip().split()

        # Separate the expression and the operator
        expression = prediction[:-2]  # All except the last two elements
        operator = prediction[-2]  # The operator (> < >= <= =)
        value_to_compare = int(prediction[-1])  # The value to compare

        # Calculate the value of the expression
        total = 0.0
        for token in expression:
            if token in outcomes:
                total += outcomes[token]
            elif token == '+':
                continue  # Ignore the addition operator

        # Compare according to the operator
        if operator == '>':
            is_correct = total > value_to_compare
        elif operator == '<':
            is_correct = total < value_to_compare
        elif operator == '>=':
            is_correct = total >= value_to_compare
        elif operator == '<=':
            is_correct = total <= value_to_compare
        elif operator == '=':
            # Equality comparison considering floating-point precision
            is_correct = abs(total - value_to_compare) < 1e-6
        else:
            raise ValueError("Unknown operator")

        # Print the result
        if is_correct:
            print(f"Guess #{guess_number} was correct.")
        else:
            print(f"Guess #{guess_number} was incorrect.")

