def calculate_fibonacci(limit):
    fib_sequence = [1, 2]
    while fib_sequence[-1] <= limit:
        fib_sequence.append(fib_sequence[-1] + fib_sequence[-2])
    return fib_sequence[:-1]

def zeckendorf_representation(value):
    fib_sequence = calculate_fibonacci(value)
    representation = []

    while value > 0:
        for i in range(len(fib_sequence)-1, -1, -1):
            if fib_sequence[i] <= value:
                representation.append(fib_sequence[i])
                value -= fib_sequence[i]
                break

    return representation

