    if modulus <= 0:
        return 0

    first, second = 0, 1
    series = [(0, 1)]

    while True:
        next_first = second % modulus
        next_second = (first + second) % modulus

        if (next_first, next_second) == series[0]:
            return len(series)

        first, second = next_first, next_second
        series.append((first, second))

