def fib_series(limit):
    seq = [1, 2]
    while True:
        next_val = seq[-1] + seq[-2]
        if next_val > limit:
            break
        seq.append(next_val)
    return seq

def fib_to_base(num):
    series = fib_series(num)
    output = []

    for f in reversed(series):
        if f <= num:
            output.append('1')
            num -= f
        elif output:
            output.append('0')

    return ''.join(output)

