def format_poly(coef):
    terms = []
    for i, coeff in enumerate(coef):
        deg = len(coef) - 1 - i
        if coeff != 0:
            if deg == 0:
                terms.append(f"{coeff}")
            elif deg == 1:
                terms.append(f"{'' if coeff == 1 else '-' if coeff == -1 else coeff}x")
            else:
                terms.append(f"{'' if coeff == 1 else '-' if coeff == -1 else coeff}x^{deg}")

    if not terms:
        return "0"

    poly = terms[0]
    for term in terms[1:]:
        if term.startswith('-'):
            poly += f" {term}"
        else:
            poly += f" + {term}"

    return poly.replace(' -', ' - ')

