from collections import deque

def prime_check(num):
    if num < 2:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def generate_prime_nums(start, end):
    prime_nums = []
    for num in range(start, end + 1):
        if prime_check(num):
            prime_nums.append(num)
    return prime_nums

def create_neighbor_primes(prime, prime_set):
    neighbor_primes = []
    prime_str = str(prime)
    for i in range(4):
        for digit in '0123456789':
            if prime_str[i] != digit:
                new_prime = prime_str[:i] + digit + prime_str[i+1:]
                new_prime_num = int(new_prime)
                if new_prime_num in prime_set:
                    neighbor_primes.append(new_prime_num)
    return neighbor_primes

def breadth_first_search_shortest_path(start, end, prime_set):
    if start == end:
        return 0

    queue = deque([(start, 0)])  # (current_prime, cost)
    visited = set()
    visited.add(start)

    while queue:
        current, cost = queue.popleft()
        for neighbor in create_neighbor_primes(current, prime_set):
            if neighbor not in visited:
                if neighbor == end:
                    return cost + 1
                visited.add(neighbor)
                queue.append((neighbor, cost + 1))
    return -1

def calculate_min_cost(test_cases):
    results = []
    prime_set = set(generate_prime_nums(1000, 9999))

    for start, end in test_cases:
        result = breadth_first_search_shortest_path(start, end, prime_set)
        results.append("Imposible" if result == -1 else result)

    return results

