import heapq

def analyze_structure(operations):
    stack = []
    queue = []
    priority_queue = []
    stack_valid = True
    queue_valid = True
    priority_queue_valid = True

    for operation, value in operations:
        if operation == 1:  # Insert element
            stack.append(value)
            queue.append(value)
            heapq.heappush(priority_queue, -value)  # Using negatives to simulate a max queue
        elif operation == 2:  # Remove element
            if stack_valid:
                if not stack or stack.pop() != value:
                    stack_valid = False
            if queue_valid:
                if not queue or queue.pop(0) != value:
                    queue_valid = False
            if priority_queue_valid:
                if not priority_queue or -heapq.heappop(priority_queue) != value:
                    priority_queue_valid = False

    # Determine the type of data structure
    valid_count = [stack_valid, queue_valid, priority_queue_valid].count(True)
    if valid_count > 1:
        return "not sure"
    elif valid_count == 0:
        return "impossible"
    else:
        if stack_valid:
            return "stack"
        elif queue_valid:
            return "queue"
        elif priority_queue_valid:
            return "priority queue"

