def evaluate_structure(operations):
    from collections import deque
    import heapq

    stack = []
    queue = deque()
    priority_queue = []

    is_stack = True
    is_queue = True
    is_priority_queue = True

    for operation in operations:
        action, value = operation

        if action == 1:
            if is_stack:
                stack.append(value)
            if is_queue:
                queue.append(value)
            if is_priority_queue:
                heapq.heappush(priority_queue, -value)
        elif action == 2:
            if is_stack:
                if stack and stack[-1] == value:
                    stack.pop()
                else:
                    is_stack = False
            if is_queue:
                if queue and queue[0] == value:
                    queue.popleft()
                else:
                    is_queue = False
            if is_priority_queue:
                if priority_queue and -priority_queue[0] == value:
                    heapq.heappop(priority_queue)
                else:
                    is_priority_queue = False

    if is_stack and not is_queue and not is_priority_queue:
        return "stack"
    elif not is_stack and is_queue and not is_priority_queue:
        return "queue"
    elif not is_stack and not is_queue and is_priority_queue:
        return "priority queue"
    elif not is_stack and not is_queue and not is_priority_queue:
        return "impossible"
    else:
        return "not sure"

