import math

def find_power(p):
    max_x = -1
    max_y = -1
    max_y_possible = int(math.log2(p)) + 2

    for y in range(2, max_y_possible):
        x = int(round(p ** (1 / y)))

        if x > 1 and pow(x, y) == p:
            if x > max_x:
                max_x = x
                max_y = y

    if max_x == -1:
        return None
    else:
        return (max_x, max_y)

