def check_prime(n):
    """Checks if a number n is prime."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_rotations(num):
    """Generates all possible rotations of a number."""
    rotations = []
    num_str = str(num)
    length = len(num_str)
    for i in range(length):
        # Rotate the number
        rotated = num_str[i:] + num_str[:i]
        rotations.append(int(rotated))
    return rotations

def is_circular_prime(num):
    """Checks if a number is a circular prime."""
    rotations = generate_rotations(num)
    for rotation in rotations:
        if not check_prime(rotation):
            return False
    return True

