def flip(stack, pos):
    return stack[:pos][::-1] + stack[pos:]

def find_max(stack, limit):
    return max(range(limit), key=lambda i: stack[i])

def flip_sort(stack):
    n = len(stack)
    flips = []

    for i in range(n, 1, -1):
        max_pos = find_max(stack, i)
        if max_pos != i - 1:
            if max_pos != 0:
                flips.append(n - max_pos)
                stack = flip(stack, max_pos + 1)
            flips.append(n - i + 1)
            stack = flip(stack, i)

    return flips

