def factorize(limit):
    factor_counts = [0] * (limit + 1)
    for i in range(2, limit + 1):
        if factor_counts[i] == 0:
            for j in range(i, limit + 1, i):
                factor_counts[j] += i
    return factor_counts

def locate_consecutive_pairs(start, end, factor_counts):
    return [(num, num + 1) for num in range(start, end) if factor_counts[num] == factor_counts[num + 1]]

