def find_number_with_most_prime_factors(A, B, prime_factors):
    highest_factors = 0
    result_number = 0
    for num in range(A, B + 1):
        if prime_factors[num] > highest_factors or (prime_factors[num] == highest_factors and num > result_number):
            highest_factors = prime_factors[num]
            result_number = num
    return result_number, highest_factors

