def check_palindrome(s):
    n = len(s)
    table = [[0] * n for _ in range(n)]

    for i in range(n):
        table[i][i] = 1

    for span in range(2, n + 1):
        for start in range(n - span + 1):
            end = start + span - 1
            if s[start] == s[end] and span == 2:
                table[start][end] = 2
            elif s[start] == s[end]:
                table[start][end] = table[start + 1][end - 1] + 2
            else:
                table[start][end] = max(table[start][end - 1], table[start + 1][end])

    return table[0][n - 1]

