from collections import deque

def calculate_time(num_cases, cases):
    outcomes = []
    for scenario in cases:
        n, m, tasks = scenario
        priority_queue = deque([(priority, idx) for idx, priority in enumerate(tasks)])
        elapsed_time = 0

        while priority_queue:
            task = priority_queue.popleft()
            if any(task[0] < other_task[0] for other_task in priority_queue):
                priority_queue.append(task)
            else:
                elapsed_time += 1
                if task[1] == m:
                    outcomes.append(elapsed_time)
                    break
    return outcomes

