def calculate_power(base, exponent):
    if exponent == 0: return 1
    if exponent % 2 == 0: return (calculate_power(base, exponent // 2)) ** 2
    else: return base * (calculate_power(base, exponent // 2)) ** 2

def sub_factorial(number):
    if number == 2: return 1
    return (number * sub_factorial(number - 1)) + calculate_power(-1, number)

