from queue import PriorityQueue

def analyze_data_structure(n, operations):
    stack_mode = True
    queue_mode = True
    priority_queue_mode = True
    stack = []
    queue = []
    priority_queue = PriorityQueue()
    for operation in operations:
        operation_type, value = operation.split()
        if operation_type == '1':
            value = int(value)
            stack.append(value)
            queue.append(value)
            priority_queue.put(-value)
        elif operation_type == '2':
            value = int(value)
            if not stack or stack.pop() != value:
                stack_mode = False
            if not queue or queue.pop(0) != value:
                queue_mode = False
            if not priority_queue.empty() and -priority_queue.get() != value:
                priority_queue_mode = False

    # Determine the data structure
    if stack_mode and not queue_mode and not priority_queue_mode:
        return "stack"
    elif not stack_mode and queue_mode and not priority_queue_mode:
        return "queue"
    elif not stack_mode and not queue_mode and priority_queue_mode:
        return "priority queue"
    elif not stack_mode and not queue_mode and not priority_queue_mode:
        return "impossible"
    else:
        return "not sure"

