import math

def compute_series(n_max):
    series = [0] * (n_max + 1)
    series[0] = 0
    series[1] = 1
    for n in range(2, n_max + 1):
        series[n] = 3 * series[n-2] - 2 * series[n-1]
    return series

def calculate_value(series, n):
    return series[n]**2 + 2**(n + 2)

