def sortAscending(a, b, c):
    sides = [a, b, c]
    for i in range(3):
        for j in range(0, 2 - i):
            if sides[j] > sides[j + 1]:
                sides[j], sides[j + 1] = sides[j + 1], sides[j]
    return sides

def isRightTriangle(sides):
    return sides[2] ** 2 == sides[0] ** 2 + sides[1] ** 2

def isInvalidTriangle(sides):
    return sides[2] > sides[0] + sides[1]

def isScaleneTriangle(sides):
    return sides[0] != sides[1] and sides[0] != sides[2] and sides[1] != sides[2]

def isEquilateralTriangle(sides):
    return sides[0] == sides[1] == sides[2]

