def handle_command():
    max_heap = []

    while True:
        try:
            command = input().strip().split()
            action = command[0]

            if action == "S" and len(command) == 2:
                number = int(command[1])
                heapq.heappush(max_heap, -number)

            elif action == "A":
                if max_heap:
                    print(-max_heap[0])
                else:
                    print("Error")

            elif action == "R":
                if max_heap:
                    heapq.heappop(max_heap)
                else:
                    print("Error")

            elif action == "I" and len(command) == 2:
                increment = int(command[1])
                if max_heap:
                    max_value = -heapq.heappop(max_heap)
                    new_value = max_value + increment
                    heapq.heappush(max_heap, -new_value)
                else:
                    print("Error")

            elif action == "D" and len(command) == 2:
                decrement = int(command[1])
                if max_heap:
                    max_value = -heapq.heappop(max_heap)
                    new_value = max_value - decrement
                    heapq.heappush(max_heap, -new_value)
                else:
                    print("Error")

            elif action == "T":
                break

        except (ValueError, IndexError):
