def decompose(n):
    even_sum = 0
    odd_sum = 0
    toggle = True
    while n > 0:
        digit = n % 10
        n //= 10
        if toggle:
            odd_sum += digit
            toggle = False
        else:
            even_sum += digit
            toggle = True
    return even_sum == odd_sum

