import heapq

def process_commands(commands):
    priority_queue = []
    outcomes = []

    for command in commands:
        parts = command.split()
        action = parts[0]

        if action == 'S':
            heapq.heappush(priority_queue, -int(parts[1]))

        elif action == 'A':
            outcomes.append(-priority_queue[0] if priority_queue else "Error")

        elif action == 'R':
            if priority_queue:
                heapq.heappop(priority_queue)
            else:
                outcomes.append("Error")

        elif action in ('I', 'D'):
            if priority_queue:
                increment = int(parts[1])
                top_value = -heapq.heappop(priority_queue)
                top_value = top_value + increment if action == 'I' else top_value - increment
                heapq.heappush(priority_queue, -top_value)
            else:
                outcomes.append("Error")

        elif action == 'T':
            break

    return outcomes

