        match = re.match(r'(.+?)\s*(<=|<|=|>=|>)\s*(\d+)', prediction)
        if not match:
            continue

        left_side, op, right_value = match.groups()
        right_value = int(right_value)
        games = map(str.strip, left_side.split('+'))

        total = sum(probabilities.get(game, 0.0) for game in games)
        if operators[op](round(total, 1), right_value):
            outcomes.append(f"Guess #{idx+1} was correct.")
        else:
            outcomes.append(f"Guess #{idx+1} was incorrect.")

    print("\n".join(outcomes))

def find_fibonacci_period(b):
    fib_series = [0, 1]
    prev, curr = 0, 1

    for _ in range(b * b):
        prev, curr = curr, (prev + curr) % b
        fib_series.append(curr)

        if prev == 0 and curr == 1:
            break

    return len(fib_series) - 2

