def round_decimal(x):
    return int(x + 0.5) if x >= 0 else int(x - 0.5)

def process_input():
    import sys
    lines = sys.stdin.read().split('\n')
    return int(lines[0]), [line.strip() for line in lines[1:]]

def calculate_vowel_percentages(s):
    vowels = {'a': 0, 'e': 0, 'i': 0, 'o': 0, 'u': 0}
    total = len(s)
    for char in s:
        if char in vowels:
            vowels[char] += 1
    return vowels, total

def main():
    cases, inputs = process_input()
    for i, s in enumerate(inputs, start=1):
        vowel_counts, total_chars = calculate_vowel_percentages(s)
        print(f"Caso {i}:")
        for vowel in sorted(vowel_counts):
            percentage = (vowel_counts[vowel] / total_chars) * 100 if total_chars else 0
            rounded_percentage = round_decimal(percentage * 100) / 100
            print(f"{vowel}= {rounded_percentage:.2f}")

main()

def generate_primes(limit):
    sieve = [True] * (limit + 1)
    p = 2
    while p * p <= limit:
        if sieve[p]:
            for i in range(p * p, limit + 1, p):
                sieve[i] = False
        p += 1
    return [p for p in range(2, limit + 1) if sieve[p]]

def calculate_prime_factors_sum(number, prime_list):
    factors_sum = 0
    original_number = number
    for prime in prime_list:
        if prime * prime > number:
            break
        if number % prime == 0:
            factors_sum += prime
            while number % prime == 0:
                number //= prime
    if number > 1:
        factors_sum += number
    return factors_sum

def identify_ruth_aaron_pairs(start, end, prime_numbers):
    pair_list = []
    prime_sum_store = {}

    for number in range(start, end):
        if number not in prime_sum_store:
            prime_sum_store[number] = calculate_prime_factors_sum(number, prime_numbers)
        if (number + 1) not in prime_sum_store:
            prime_sum_store[number + 1] = calculate_prime_factors_sum(number + 1, prime_numbers)

        if prime_sum_store[number] == prime_sum_store[number + 1]:
            pair_list.append((number, number + 1))

    return pair_list

def primary_function():
    # Create primes up to 1,000,000
    upper_bound = 1000000
    primes = generate_primes(upper_bound)

    import sys
    input_data = sys.stdin.read
    input_lines = input_data().strip().splitlines()

    for line in input_lines:
        if line.strip():
            lower_limit, upper_limit = map(int, line.split())
            pairs = identify_ruth_aaron_pairs(lower_limit, upper_limit, primes)
            for pair in pairs:
                print(f"{pair[0]} {pair[1]}")

if __name__ == "__main__":
    primary_function()
